n    // function_name may contain single underscores.\\n    \'(?:__)?[a-zA-Z]{2,}_[a-zA-Z](?:_?[a-zA-Z])+:[a-zA-Z]*\',\\n    // A variable \\\\scope_module_and_name_type or \\\\scope__module_ane_name_type,\\n    // where scope is one of l, g or c, type needs at least two characters\\n    // and module_and_name may contain single underscores.\\n    \'[lgc]__?[a-zA-Z](?:_?[a-zA-Z])*_[a-zA-Z]{2,}\',\\n    // A quark \\\\q_the_name or \\\\q__the_name or\\n    // scan mark \\\\s_the_name or \\\\s__vthe_name,\\n    // where variable_name needs at least two characters and\\n    // may contain single underscores.\\n    \'[qs]__?[a-zA-Z](?:_?[a-zA-Z])+\',\\n    // Other LaTeX3 macro names that are not covered by the three rules above.\\n    \'use(?:_i)?:[a-zA-Z]*\',\\n    \'(?:else|fi|or):\',\\n    \'(?:if|cs|exp):w\',\\n    \'(?:hbox|vbox):n\',\\n    \'::[a-zA-Z]_unbraced\',\\n    \'::[a-zA-Z:]\'\\n  ].map(pattern => pattern + \'(?![a-zA-Z:_])\').join(\'|\'));\\n  const L2_VARIANTS = [\\n    { begin: /[a-zA-Z@]+/ }, // control word\\n    { begin: /[^a-zA-Z@]?/ } // control symbol\\n  ];\\n  const DOUBLE_CARET_VARIANTS = [\\n    { begin: /\\\\^{6}[0-9a-f]{6}/ },\\n    { begin: /\\\\^{5}[0-9a-f]{5}/ },\\n    { begin: /\\\\^{4}[0-9a-f]{4}/ },\\n    { begin: /\\\\^{3}[0-9a-f]{3}/ },\\n    { begin: /\\\\^{2}[0-9a-f]{2}/ },\\n    { begin: /\\\\^{2}[\\\\u0000-\\\\u007f]/ }\\n  ];\\n  const CONTROL_SEQUENCE = {\\n    className: \'keyword\',\\n    begin: /\\\\\\\\/,\\n    relevance: 0,\\n    contains: [\\n      {\\n        endsParent: true,\\n        begin: KNOWN_CONTROL_WORDS\\n      },\\n      {\\n        endsParent: true,\\n        begin: L3_REGEX\\n      },\\n      {\\n        endsParent: true,\\n        variants: DOUBLE_CARET_VARIANTS\\n      },\\n      {\\n        endsParent: true,\\n        relevance: 0,\\n        variants: L2_VARIANTS\\n      }\\n    ]\\n  };\\n  const MACRO_PARAM = {\\n    className: \'params\',\\n    relevance: 0,\\n    begin: /#+\\\\d?/\\n  };\\n  const DOUBLE_CARET_CHAR = {\\n    // relevance: 1\\n    variants: DOUBLE_CARET_VARIANTS };\\n  const SPECIAL_CATCODE = {\\n    className: \'built_in\',\\n    relevance: 0,\\n    begin: /[$&^_]/\\n  };\\n  const MAGIC_COMMENT = {\\n    className: \'meta\',\\n    begin: /% ?!(T[eE]X|tex|BIB|bib)/,\\n    end: \'$\',\\n    relevance: 10\\n  };\\n  const COMMENT = hljs.COMMENT(\\n    \'%\',\\n    \'$\',\\n    { relevance: 0 }\\n  );\\n  const EVERYTHING_BUT_VERBATIM = [\\n    CONTROL_SEQUENCE,\\n    MACRO_PARAM,\\n    DOUBLE_CARET_CHAR,\\n    SPECIAL_CATCODE,\\n    MAGIC_COMMENT,\\n    COMMENT\\n  ];\\n  const BRACE_GROUP_NO_VERBATIM = {\\n    begin: /\\\\{/,\\n    end: /\\\\}/,\\n    relevance: 0,\\n    contains: [\\n      \'self\',\\n      ...EVERYTHING_BUT_VERBATIM\\n    ]\\n  };\\n  const ARGUMENT_BRACES = hljs.inherit(\\n    BRACE_GROUP_NO_VERBATIM,\\n    {\\n      relevance: 0,\\n      endsParent: true,\\n      contains: [\\n        BRACE_GROUP_NO_VERBATIM,\\n        ...EVERYTHING_BUT_VERBATIM\\n      ]\\n    }\\n  );\\n  const ARGUMENT_BRACKETS = {\\n    begin: /\\\\[/,\\n    end: /\\\\]/,\\n    endsParent: true,\\n    relevance: 0,\\n    contains: [\\n      BRACE_GROUP_NO_VERBATIM,\\n      ...EVERYTHING_BUT_VERBATIM\\n    ]\\n  };\\n  const SPACE_GOBBLER = {\\n    begin: /\\\\s+/,\\n    relevance: 0\\n  };\\n  const ARGUMENT_M = [ ARGUMENT_BRACES ];\\n  const ARGUMENT_O = [ ARGUMENT_BRACKETS ];\\n  const ARGUMENT_AND_THEN = function(arg, starts_mode) {\\n    return {\\n      contains: [ SPACE_GOBBLER ],\\n      starts: {\\n        relevance: 0,\\n        contains: arg,\\n        starts: starts_mode\\n      }\\n    };\\n  };\\n  const CSNAME = function(csname, starts_mode) {\\n    return {\\n      begin: \'\\\\\\\\\\\\\\\\\' + csname + \'(?![a-zA-Z@:_])\',\\n      keywords: {\\n        $pattern: /\\\\\\\\[a-zA-Z]+/,\\n        keyword: \'\\\\\\\\\' + csname\\n      },\\n      relevance: 0,\\n      contains: [ SPACE_GOBBLER ],\\n      starts: starts_mode\\n    };\\n  };\\n  const BEGIN_ENV = function(envname, starts_mode) {\\n    return hljs.inherit(\\n      {\\n        begin: \'\\\\\\\\\\\\\\\\begin(?=[ \\\\t]*(\\\\\\\\r?\\\\\\\\n[ \\\\t]*)?\\\\\\\\{\' + envname + \'\\\\\\\\})\',\\n        keywords: {\\n          $pattern: /\\\\\\\\[a-zA-Z]+/,\\n          keyword: \'\\\\\\\\begin\'\\n        },\\n        relevance: 0,\\n      },\\n      ARGUMENT_AND_THEN(ARGUMENT_M, starts_mode)\\n    );\\n  };\\n  const VERBATIM_DELIMITED_EQUAL = (innerName = \\"string\\") => {\\n    return hljs.END_SAME_AS_BEGIN({\\n      className: innerName,\\n      begin: /(.|\\\\r?\\\\n)/,\\n      end: /(.|\\\\r?\\\\n)/,\\n      excludeBegin: true,\\n      excludeEnd: true,\\n      endsParent: true\\n    });\\n  };\\n  const VERBATIM_DELIMITED_ENV = function(envname) {\\n    return {\\n      className: \'string\',\\n      end: \'(?=\\\\\\\\\\\\\\\\end\\\\\\\\{\' + envname + \'\\\\\\\\})\'\\n    };\\n  };\\n\\n  const VERBATIM_DELIMITED_BRACES = (innerName = \\"string\\") => {\\n    return {\\n      relevance: 0,\\n      begin: /\\\\{/,\\n      starts: {\\n        endsParent: true,\\n        contains: [\\n          {\\n            className: innerName,\\n            end: /(?=\\\\})/,\\n            endsParent: true,\\n            contains: [\\n              {\\n                begin: /\\\\{/,\\n                end: /\\\\}/,\\n                relevance: 0,\\n                contains: [ \\"self\\" ]\\n              }\\n            ],\\n          }\\n        ]\\n      }\\n    };\\n  };\\n  const VERBATIM = [\\n    ...[\\n      \'verb\',\\n      \'lstinline\'\\n    ].map(csname => CSNAME(csname, { contains: [ VERBATIM_DELIMITED_EQUAL() ] })),\\n    CSNAME(\'mint\', ARGUMENT_AND_THEN(ARGUMENT_M, { contains: [ VERBATIM_DELIMITED_EQUAL() ] })),\\n    CSNAME(\'mintinline\', ARGUMENT_AND_THEN(ARGUMENT_M, { contains: [\\n      VERBATIM_DELIMITED_BRACES(),\\n      VERBATIM_DELIMITED_EQUAL()\\n    ] })),\\n    CSNAME(\'url\', { contains: [\\n      VERBATIM_DELIMITED_BRACES(\\"link\\"),\\n      VERBATIM_DELIMITED_BRACES(\\"link\\")\\n    ] }),\\n    CSNAME(\'hyperref\', { contains: [ VERBATIM_DELIMITED_BRACES(\\"link\\") ] }),\\n    CSNAME(\'href\', ARGUMENT_AND_THEN(ARGUMENT_O, { contains: [ VERBATIM_DELIMITED_BRACES(\\"link\\") ] })),\\n    ...[].concat(...[\\n      \'\',\\n      \'\\\\\\\\*\'\\n    ].map(suffix => [\\n      BEGIN_ENV(\'verbatim\' + suffix, VERBATIM_DELIMITED_ENV(\'verbatim\' + suffix)),\\n      BEGIN_ENV(\'filecontents\' + suffix, ARGUMENT_AND_THEN(ARGUMENT_M, VERBATIM_DELIMITED_ENV(\'filecontents\' + suffix))),\\n      ...[\\n        \'\',\\n        \'B\',\\n        \'L\'\\n      ].map(prefix =>\\n        BEGIN_ENV(prefix + \'Verbatim\' + suffix, ARGUMENT_AND_THEN(ARGUMENT_O, VERBATIM_DELIMITED_ENV(prefix + \'Verbatim\' + suffix)))\\n      )\\n    ])),\\n    BEGIN_ENV(\'minted\', ARGUMENT_AND_THEN(ARGUMENT_O, ARGUMENT_AND_THEN(ARGUMENT_M, VERBATIM_DELIMITED_ENV(\'minted\')))),\\n  ];\\n\\n  return {\\n    name: \'LaTeX\',\\n    aliases: [ \'tex\' ],\\n    contains: [\\n      ...VERBATIM,\\n      ...EVERYTHING_BUT_VERBATIM\\n    ]\\n  };\\n}\\n\\nmodule.exports = latex;\\n","/*\\nLanguage: LDIF\\nContributors: Jacob Childress <jacobc@gmail.com>\\nCategory: enterprise, config\\nWebsite: https://en.wikipedia.org/wiki/LDAP_Data_Interchange_Format\\n*/\\n\\n/** @type LanguageFn */\\nfunction ldif(hljs) {\\n  return {\\n    name: \'LDIF\',\\n    contains: [\\n      {\\n        className: \'attribute\',\\n        match: \'^dn(?=:)\',\\n        relevance: 10\\n      },\\n      {\\n        className: \'attribute\',\\n        match: \'^\\\\\\\\w+(?=:)\'\\n      },\\n      {\\n        className: \'literal\',\\n        match: \'^-\'\\n      },\\n      hljs.HASH_COMMENT_MODE\\n    ]\\n  };\\n}\\n\\nmodule.exports = ldif;\\n","/*\\nLanguage: Leaf\\nDescription: A Swift-based templating language created for the Vapor project.\\nWebsite: https://docs.vapor.codes/leaf/overview\\nCategory: template\\n*/\\n\\nfunction leaf(hljs) {\\n